fn gcd_calc(mut m: u32, mut n: u32) -> u32 {
    // Precondition: m > 0, n > 0
    // The loop invariant is gcd(m, n) = gcd(original_m, original_n),
    // and both m, n remain > 0 throughout.
    while m != n {
        if m > n {
            m -= n; // strictly decreases m + n because n > 0
        } else {
            n -= m; // strictly decreases m + n because m > 0
        }
    }
    // Once m == n, that value is the GCD
    m
}

